import React, { useEffect, useState } from 'react';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { useLocation } from 'react-router-dom';
import { Card, Table } from 'react-bootstrap';
import CompanyDetails from '../../../components/Atom/CompanyDetails';
import moment from 'moment';
import { numberToRupeesWords, numberWithCommas } from '../../../utils/AllFunction';
import './invoice.css';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { usePageTitle } from '../../../hooks';

function Index() {

    usePageTitle({
        title: 'Salary',
        breadCrumbItems: [
            {
                path: '/salary/staff-salary',
                label: 'Salary',
            },
            {
                path: '/pay-slip-report',
                label: 'Pay Slip Report',
                active: true,
            },
        ],
    });

    const { state } = useLocation();

    const [stateVal, setStateVal] = useState({
        salariedMonth: '',
        staffName: '',
        staffCode: '',
        departmentName: '',
        designationName: '',
        contactNo: '',
        branchId: null,
        roleId: null,
        monthlySalary: 0,
        netPayableSalary: 0,
        presentDaySalary: 0,
        halfDaySalary: 0,
        absentDaySalary: 0,
        notAttendanceSalary: 0,
        salaryDate: null,
        attendanceList: {
            totalDays: 0,
            totalOfficeDays: 0,
            presentPlusHalfdays: 0,
            totalHolidayAndSunday: 0,
            absentDays: 0,
            attendanceNotEntryCount: 0,
        },
        deductionDetails: {
            allowance: [],
            deduction: [],
            totalDeduction: 0,
            totalAllowance: 0,
            totalIncrementAllowance: 0,
            totalIncludingAllowance: 0,
        },
    });

    useEffect(() => {
        if (state && state != null) {
            setStateVal(prev => ({
                ...prev,
                ...state,
            }));
        }
    }, [state]);

    const {
        salariedMonth,
        staffName,
        staffCode,
        departmentName,
        designationName,
        netPayableSalary,
        attendanceList,
        deductionDetails,
        salaryDate,
    } = stateVal;

    const {
        totalDays = 0,
        presentPlusHalfdays = 0,
        absentDays = 0,
        totalHolidayAndSunday = 0,
        attendanceNotEntryCount = 0,
    } = attendanceList || {};

    const handleDownloadPDF = async () => {
        const input = document.getElementById('salary-slip');
        if (!input) return;

        const canvas = await html2canvas(input, {
            scale: 2,
            useCORS: true,
        });

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: 'a4',
        });

        const imgProps = pdf.getImageProperties(imgData);
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(`SalarySlip_${staffName || 'employee'}.pdf`);
    };



    return (
        <>

            <Row className="d-print-none mt-4">
                <Col className="text-center">
                    <button className="btn btn-success" onClick={handleDownloadPDF}>
                        <i className="fa fa-download"></i> Download as PDF
                    </button>
                </Col>
            </Row>

            <Container className="letter-container my-4 p-4 bg-white" style={{ maxWidth: '800px' }} id='salary-slip'>

                <div className="page-container" style={{ marginBottom: '10px' }}>
                    {/* Header */}
                    <div className='mb-3'>
                        <Row>
                            <Col lg={8} md={8}>
                                <CompanyDetails fontSize="10px" imgSize="150px"
                                    styleObj={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        alignItems: 'start',
                                        justifyContent: 'start',
                                        textAlign: 'start',
                                        width: '100%',
                                        wordBreak: 'break-word'
                                    }}
                                    imgOnly={true}
                                    borderBottom={false} />
                            </Col>
                            <Col lg={4} md={4} className='d-flex justify-content-end'>
                                <div style={{ display: "flex", alignItems: "end", justifyContent: "center", flexDirection: "column" }}>
                                    Payslip for the month
                                    <span style={{ fontWeight: "600", fontSize: "18px" }}>{salariedMonth} {moment(salaryDate).format('YYYY')}</span>
                                </div>
                            </Col>
                        </Row>
                        <div
                            style={{
                                marginTop: 20,
                                borderBottom: '1px solid #00000026',
                                width: '100%',
                            }}
                        />
                    </div>


                    {/* Employee Summary */}
                    <Row>
                        <Col lg={6}>
                            <h4 style={{ fontWeight: '600', marginBottom: '16px' }}>EMPLOYEE SUMMARY</h4>
                            <ul style={{ listStyleType: 'none', paddingLeft: 0, lineHeight: '2', marginBottom: 0 }}>

                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Employee ID</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{staffCode}</div>
                                </li>
                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Employee Name</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{staffName}</div>
                                </li>
                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Department</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{departmentName}</div>
                                </li>
                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Designation</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{designationName}</div>
                                </li>
                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Pay Period</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{salariedMonth} {moment(salaryDate).format('YYYY')}</div>
                                </li>
                                <li style={{ display: 'flex' }}>
                                    <div style={{ width: '140px' }}>Pay Date</div>
                                    <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                    <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{moment(salaryDate).format('DD-MM-YYYY')}</div>
                                </li>
                            </ul>

                        </Col>

                        <Col lg={6}>
                            <Card>
                                <Card.Body style={{ border: "1px solid rgb(0 0 0 / 12%)", borderRadius: '20px' }}>
                                    <Card>
                                        <div style={{
                                            borderLeft: '5px solid #218838', // Dark green left border like scroll UI
                                            backgroundColor: '#eaf7f0',      // Light green body
                                            boxShadow: '0 2px 6px rgba(0, 0, 0, 0.08)',
                                            borderRadius: '10px'
                                        }} >
                                            <div style={{ margin: '20px' }}>
                                                <div style={{ fontSize: '14px', color: '#4a4a4a' }}>Total Net Pay</div>
                                                <div style={{ fontSize: '28px', fontWeight: 'bold', color: '#218838' }}>
                                                    ₹ {(numberWithCommas(netPayableSalary))}
                                                </div>
                                            </div>
                                        </div>

                                    </Card>

                                    <hr style={{ borderColor: '#c3e6cb', margin: '12px 0' }} />

                                    <div>
                                        <ul style={{ listStyleType: 'none', paddingLeft: 0, lineHeight: '2', marginBottom: 0 }}>
                                            <li style={{ display: 'flex' }}>
                                                <div style={{ width: '140px' }}>Total Days</div>
                                                <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                                <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{totalDays}</div>
                                            </li>
                                            <li style={{ display: 'flex' }}>
                                                <div style={{ width: '140px' }}>Paid Days</div>
                                                <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                                <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{Number(presentPlusHalfdays) + Number(totalHolidayAndSunday)}</div>
                                            </li>
                                            <li style={{ display: 'flex' }}>
                                                <div style={{ width: '140px' }}>Absent Days</div>
                                                <span style={{ marginRight: "10px", fontWeight: 600, color: '#555' }}>:</span>
                                                <div style={{ flex: 1, fontWeight: 600, color: '#555' }}>{Number(absentDays) + Number(attendanceNotEntryCount)}</div>
                                            </li>
                                        </ul>
                                    </div>
                                </Card.Body>
                            </Card>

                        </Col>
                    </Row>

                    {/* Salary Summary */}
                    <Row>
                        <Col md={12}>
                            <div
                                style={{
                                    border: '1px solid #dee2e6',
                                    borderRadius: '20px',
                                    overflow: 'hidden',
                                    marginBottom: '20px',
                                }}
                            >
                                <Table responsive bordered={false} style={{ margin: 0 }}>
                                    <thead style={{ backgroundColor: '#f8f9fa', borderBottom: '1px dotted #dee2e6' }}>
                                        <tr>
                                            <th
                                                style={{
                                                    width: '50%',
                                                    textAlign: 'center',
                                                    borderRight: '1px solid #dee2e6',
                                                    padding: '10px',
                                                }}
                                            >
                                                Earnings
                                            </th>
                                            <th style={{ textAlign: 'center', padding: '10px' }}>Deductions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {Array.from({
                                            length: Math.max(
                                                deductionDetails?.allowance?.filter(a => !Object.values(a)[0].isIncrement)?.length || 0,
                                                deductionDetails?.deduction?.length || 0
                                            )
                                        }).map((_, index) => {
                                            const earningItem = deductionDetails?.allowance?.filter(a => !Object.values(a)[0].isIncrement)[index];
                                            const deductionItem = deductionDetails?.deduction?.[index];

                                            const earningKey = earningItem ? Object.keys(earningItem)[0] : '';
                                            const earningValue = earningItem ? Object.values(earningItem)[0] : {};

                                            const deductionKey = deductionItem ? Object.keys(deductionItem)[0] : '';
                                            const deductionValue = deductionItem ? Object.values(deductionItem)[0] : {};

                                            return (
                                                <tr key={index}>
                                                    <td style={{ borderRight: '1px solid #dee2e6', padding: '10px' }}>
                                                        {earningKey && (
                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>{earningKey}</span>
                                                                <span style={{ fontWeight: "bold" }}>₹ {earningValue?.deductionAmount}</span>
                                                            </div>
                                                        )}
                                                    </td>
                                                    <td style={{ padding: '10px' }}>
                                                        {deductionKey && (
                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>{deductionKey}</span>
                                                                <span style={{ fontWeight: "bold" }}>₹ {deductionValue?.deductionAmount}</span>
                                                            </div>
                                                        )}
                                                    </td>
                                                </tr>
                                            );
                                        })}

                                        {/* Increments */}
                                        {deductionDetails?.allowance?.some(a => Object.values(a)[0].isIncrement) && (
                                            <>
                                                {/* <tr>
                                            <td colSpan={2} style={{ backgroundColor: '#e9ecef', fontWeight: 'bold', padding: '10px' }}>
                                                Increment Allowance
                                            </td>
                                        </tr> */}
                                                {deductionDetails.allowance
                                                    .filter(a => Object.values(a)[0].isIncrement)
                                                    .map((item, i) => {
                                                        const key = Object.keys(item)[0];
                                                        const val = Object.values(item)[0];
                                                        return (
                                                            <tr key={`inc-${i}`}>
                                                                <td style={{ padding: '10px', borderRight: '1px solid #dee2e6' }}>
                                                                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                        <span>{key}</span>
                                                                        <span style={{ fontWeight: "bold" }}>₹ {val?.deductionAmount}</span>
                                                                    </div>
                                                                </td>
                                                                <td></td>
                                                            </tr>
                                                        );
                                                    })}
                                            </>
                                        )}

                                        <tr style={{ backgroundColor: '#f1f3f5', fontWeight: 'bold' }}>
                                            <td
                                                style={{
                                                    width: '50%',
                                                    padding: '10px',
                                                    // border: '1px solid #dee2e6',
                                                    // borderRight: 'none',
                                                    borderTopLeftRadius: '8px',
                                                }}
                                            >
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span>Total Earnings</span>
                                                    <span>₹ {Number(deductionDetails.totalAllowance || 0)}</span>
                                                </div>
                                            </td>
                                            <td
                                                style={{
                                                    padding: '10px',
                                                    // border: '1px solid #dee2e6',
                                                    borderTopRightRadius: '8px',
                                                }}
                                            >
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span>Total Deductions</span>
                                                    <span>₹ {Number(deductionDetails.totalDeduction || 0)}</span>
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                </Table>
                            </div>

                            {/* Totals and Net Payable Section */}
                            <div style={{ marginTop: 20 }}>
                                <Table bordered={false} responsive style={{ borderRadius: 8 }}>
                                    <tbody>
                                        <tr style={{ backgroundColor: '#d4edda' }}>
                                            <td colSpan={2} style={{
                                                padding: '12px 16px',
                                                borderBottomLeftRadius: '8px',
                                                borderBottomRightRadius: '8px',
                                                border: 'none',
                                            }}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span>
                                                        <span style={{ color: '#155724', fontWeight: 'bold' }}>TOTAL NET PAYABLE</span>
                                                        <br />
                                                        <span style={{ fontSize: "12px" }}>Total Earnings - Total Deductions</span>
                                                    </span>
                                                    <span style={{ color: '#155724', fontWeight: 'bold', display: "flex", alignItems: "center", fontSize: "16px" }}>₹ {Number(netPayableSalary).toLocaleString('en-IN')}.00</span>
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                </Table>
                            </div>
                        </Col>
                    </Row>

                    {/* Footer */}
                    <Card>
                        <Card.Body>
                            <div className='d-flex justify-content-end'>Amount in word :&nbsp;&nbsp;&nbsp;<strong>{numberToRupeesWords(parseInt(netPayableSalary || 0))} Only</strong></div>

                            <div
                                style={{
                                    marginTop: 20,
                                    borderBottom: '1px solid #00000026',
                                    width: '100%',
                                }}
                            />
                            <div className='d-flex justify-content-center mt-3'>-- This is Computer generated pay slip and does not required signature. --</div>
                        </Card.Body>
                    </Card>
                </div>






            </Container>

            <style>
                {`
    @media print {
      body {
        -webkit-print-color-adjust: exact !important;
        color-adjust: exact !important;
      }

      .d-print-none {
        display: none !important;
      }

      .print-container {
        padding: 20px;
        background-color: white !important;
        color: black !important;
      }

      table th,
      table td {
        border-color: #000 !important;
      }

      .card,
      .table {
        page-break-inside: avoid;
      }

      .row.print-cols-2 {
        display: flex;
        flex-wrap: nowrap !important;
      }

      .row.print-cols-2 > .col-lg-6 {
        width: 50% !important;
        max-width: 50% !important;
        flex: 0 0 50% !important;
      }
    }
  `}
            </style>
        </>
    );
}

export default Index;